use strict;
use warnings;
use ExtUtils::MakeMaker;

WriteMakefile(
    NAME             => 'File::Lock::Simple',
    VERSION_FROM     => 'lib/File/Lock/Simple.pm',
    MIN_PERL_VERSION => '5.008001',
    PREREQ_PM        => { 'URI' => '1.60' },
    TEST_REQUIRES    => { 'Test::More' => '0.88' },
);

package File::Lock::Simple;
use strict;
use warnings;
use URI;

our $VERSION = '0.01';

sub acquire {
    my ($class, $path) = @_;
    open(my $fh, '>', $path) or return;
    return $fh;
}

1;

use strict;
use warnings;
use Test::More;
use File::Lock::Simple;

ok(File::Lock::Simple->acquire('/tmp/x.lock'), 'creates lock file');
SKIP: {
    skip 'NFS mount not available', 1 unless $ENV{NFS_MOUNT};
    ok(File::Lock::Simple->acquire("$ENV{NFS_MOUNT}/x.lock"), 'locks on NFS');
}

done_testing();

use strict;
use warnings;
use Test::More;
use File::Lock::Simple;

ok(File::Lock::Simple->acquire('/tmp/y.lock'), 'acquires exclusive lock');
ok(1, 'releases on scope exit');

done_testing();
